window.renderSilverCase=(t,href)=>{
 const page=n=>`assets/silver-report/page-${String(n).padStart(2,'0')}.webp`;
 const chapters=[[1,'封面','Cover'],[2,'目录','Contents'],[5,'序言','Foreword'],[10,'趋势一','Trend 1'],[20,'趋势二','Trend 2'],[30,'趋势三','Trend 3'],[37,'趋势四','Trend 4'],[44,'趋势五','Trend 5'],[49,'趋势六','Trend 6'],[56,'趋势七','Trend 7'],[60,'趋势八','Trend 8'],[65,'报告署名','Credits']];
 const tiles=(nums)=>nums.map(n=>`<button class="silver-tile" type="button" data-silver-zoom="${n}" aria-label="${t('放大报告第','Enlarge report page ')}${n}${t('页','')}"><img src="${page(n)}" alt="${t('报告第','Report page ')}${n}${t('页','')}" loading="lazy"><span>${String(n).padStart(2,'0')}</span></button>`).join('');
 return `<figure class="silver-tablet-overview" style="margin:0;background:#f2f6f8"><img src="assets/silver-report/tablet-overview.png" alt="${t('银发加AI报告平板封面与内页展示','AI and ageing report tablet cover and interior showcase')}" width="2448" height="1556" loading="eager" fetchpriority="high" style="display:block;width:100%;height:auto"></figure><section class="silver-intro"><div class="silver-intro-copy"><p>${t('本次《“银发＋AI”应用趋势报告》面向医院专家，受众年龄主要集中在40—60岁。设计以信息可读性为重点，采用较大的标题与正文字号，结合清晰的层级和充足留白，确保在手机、iPad等电子设备上阅读时，内容依然清晰、舒适。','Created for hospital experts, primarily aged 40–60, the report puts readability first. Generous title and body sizes, clear hierarchy and ample white space support comfortable reading on phones and tablets.')}</p><p>${t('色彩延续阿里巴巴品牌的标志性橙色，结合简约的科技感版式与视觉元素，呼应“AI”主题的前沿性。通过统一的图表语言与严谨的信息结构，在专业、可信的内容表达和鲜明的品牌辨识度之间取得平衡。','Alibaba’s signature orange is paired with restrained, technology-inspired layouts and visual elements. Consistent charts and a rigorous information structure balance professional communication with a distinctive brand identity.')}</p></div><div class="silver-intro-meta"><span>${t('项目 / 报告署名：浙江开放大学 / 阿里巴巴 / 阿里研究院','Report credits: Zhejiang Open University / Alibaba / AliResearch')}</span><span>${t('年份：2025','Year: 2025')}</span><span>${t('服务：报告视觉 / 信息层级 / 图表与版式','Services: Report design / Information hierarchy / Charts & layout')}</span></div></section><article class="silver-case"><section class="silver-showcase"><div class="silver-device-composition"><div class="silver-tablet"><div class="silver-tablet-screen">${tiles([11,13]).replaceAll('loading="lazy"','loading="eager" decoding="async" width="1203" height="1701"')}</div></div></div></section>

<section class="silver-detail-replacement"><div class="silver-live-detail-top"><img src="assets/silver-report/detail-chart.jpg" alt="${t('AI使用情况折线图','AI usage chart')}" width="1400" height="1540" loading="lazy"><div class="silver-live-detail-copy"><h2>${t('重点更明确，<br>数据更易读。','Clear emphasis.<br>Readable data.')}</h2><p>${t('橙色承担标题与关键结论的强调，图表以克制的辅助色区分类别。通过清晰的标注、图文间距与留白，让数据成为正文叙事的一部分，而不是额外的阅读负担。','Orange highlights titles and key findings; restrained supporting colours distinguish data categories. Clear labels, spacing and white space make charts part of the narrative, rather than an additional reading burden.')}</p></div></div><img src="assets/silver-report/detail-bottom.jpg" alt="${t('报告观点与案例版式展示','Report quotation and case layouts')}" width="2800" height="2342" loading="lazy" style="display:block;width:100%;height:auto"></section>
<figure class="silver-held-ipad-showcase" style="margin:0;background:#f2f6f8"><img src="assets/silver-report/held-ipad-final.jpg" alt="${t('手持iPad展示银发加AI报告数据页面','Handheld iPad displaying the AI and ageing report')}" width="1554" height="1012" loading="lazy" style="display:block;width:100%;height:auto"></figure><figure class="silver-four-pages" style="margin:0;background:#eff3f6"><img src="assets/silver-report/four-page-layout.jpg" alt="${t('报告序言、数据图表与正文四页版式展示','Four-page editorial showcase: foreword, charts and text')}" width="2200" height="2144" loading="lazy" style="display:block;width:100%;height:auto"></figure><section class="silver-page-matrix"><img src="assets/silver-report/page-matrix.jpg" alt="${t('银发加AI应用趋势报告精选页面矩阵','AI and ageing report selected page matrix')}" width="2800" height="4189" loading="lazy" style="display:block;width:100%;height:auto"></section></article><dialog class="silver-dialog" aria-label="${t('报告页面放大阅读','Enlarged report page')}"><div class="silver-dialog-top"><span data-silver-dialog-status></span><div><button type="button" data-silver-dialog-prev aria-label="${t('上一页','Previous page')}">←</button><button type="button" data-silver-dialog-next aria-label="${t('下一页','Next page')}">→</button><button type="button" data-silver-close>${t('关闭','Close')} ×</button></div></div><div class="silver-dialog-image"></div></dialog><section class="next-project"><a href="${href('work')}">↖ ${t('返回全部案例','Back to all projects')}</a><a href="${href('project','&id=poetry')}"><span>${t('下一个项目','Next project')}</span><strong>${t('大润发 · 超市儿童诗歌展','RT-MART · Children’s Poetry Exhibition')} ↗</strong></a></section>`;
};
document.addEventListener('DOMContentLoaded',()=>{
 const book=document.querySelector('.silver-book');if(!book)return;
 const total=65,en=document.documentElement.lang==='en',mobile=matchMedia('(max-width:700px)'),reduced=matchMedia('(prefers-reduced-motion: reduce)');let mode=mobile.matches?'single':'spread',index=0,busy=false,turnTimer;
 const path=n=>`assets/silver-report/page-${String(n).padStart(2,'0')}.webp`;
 const normalize=n=>mode==='spread'&&n>0?(n%2===0?n-1:n):n;
 const visiblePages=()=>mode==='single'||index===0?[index+1]:[index+1,index+2].filter(n=>n<=total);
 const render=()=>{const nums=visiblePages();book.innerHTML=nums.map(n=>`<button class="silver-page" type="button" data-page="${n}" aria-label="${en?'Enlarge page ':'放大第 '}${n}${en?'':' 页'}"><img src="${path(n)}" alt="${en?'Report page ':'报告第 '}${n}${en?'':' 页'}" draggable="false"></button>`).join('');book.classList.toggle('silver-book-single',nums.length===1);book.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>open(Number(b.dataset.page),b)));document.querySelector('.silver-page-status').textContent=`${nums.join('–')} / ${total}`;document.querySelector('[data-silver-page]').value=index+1;document.querySelector('[data-silver-range]').value=index+1;document.querySelector('[data-silver-prev]').disabled=index===0;document.querySelector('[data-silver-next]').disabled=mode==='single'?index>=total-1:index>=total-2;document.querySelectorAll('[data-silver-mode]').forEach(b=>{b.setAttribute('aria-pressed',b.dataset.silverMode===mode);b.disabled=mobile.matches&&b.dataset.silverMode==='spread'});const chapter=document.querySelector('[data-silver-chapter]');const starts=[...chapter.options].map(o=>Number(o.value));chapter.value=starts.filter(n=>n<=index+1).at(-1)||1;
 for(const n of [index+3,index+4])if(n<=total){const pre=new Image();pre.src=path(n)}
 };
 const go=(n,animate=false,direction=1)=>{if(busy)return;const next=normalize(Math.max(0,Math.min(total-1,n)));if(next===index)return;if(!animate||reduced.matches){index=next;render();return}busy=true;book.classList.add(direction>0?'silver-turn-forward':'silver-turn-back');turnTimer=setTimeout(()=>{index=next;render();book.classList.remove('silver-turn-forward','silver-turn-back');book.classList.add('silver-turn-enter');turnTimer=setTimeout(()=>{book.classList.remove('silver-turn-enter');busy=false},180)},180)};
 const turn=direction=>go(index+(mode==='single'?direction:(direction>0?(index===0?1:2):(index===1?-1:-2))),true,direction);
 document.querySelector('[data-silver-prev]').addEventListener('click',()=>turn(-1));document.querySelector('[data-silver-next]').addEventListener('click',()=>turn(1));book.addEventListener('keydown',e=>{if(e.key==='ArrowRight'){e.preventDefault();turn(1)}if(e.key==='ArrowLeft'){e.preventDefault();turn(-1)}});
 document.querySelectorAll('[data-silver-mode]').forEach(b=>b.addEventListener('click',()=>{clearTimeout(turnTimer);busy=false;book.classList.remove('silver-turn-forward','silver-turn-back','silver-turn-enter');mode=b.dataset.silverMode;index=normalize(index);render()}));
 document.querySelector('[data-silver-chapter]').addEventListener('change',e=>go(Number(e.target.value)-1));document.querySelector('.silver-jump').addEventListener('submit',e=>{e.preventDefault();go(Number(document.querySelector('[data-silver-page]').value)-1)});document.querySelector('[data-silver-range]').addEventListener('input',e=>go(Number(e.target.value)-1));
 document.querySelectorAll('[data-silver-goto]').forEach(b=>b.addEventListener('click',()=>{go(Number(b.dataset.silverGoto)-1);book.focus({preventScroll:true});document.querySelector('.silver-book-stage').scrollIntoView({behavior:reduced.matches?'instant':'smooth',block:'center'})}));
 let touch;book.addEventListener('pointerdown',e=>{if(e.pointerType==='touch')touch={x:e.clientX,y:e.clientY}});book.addEventListener('pointerup',e=>{if(!touch)return;const dx=e.clientX-touch.x,dy=e.clientY-touch.y;touch=null;if(Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy)*1.5)turn(dx<0?1:-1)});book.addEventListener('pointercancel',()=>touch=null);
 mobile.addEventListener('change',()=>{if(mobile.matches)mode='single';index=normalize(index);render()});
 const dialog=document.querySelector('.silver-dialog');let zoom=1,opener;
 const zoomRender=()=>{document.querySelector('.silver-dialog-image').innerHTML=`<img src="${path(zoom)}" alt="${en?'Report page ':'报告第 '}${zoom}${en?'':' 页'}">`;document.querySelector('[data-silver-dialog-status]').textContent=`${zoom} / ${total}`;document.querySelector('[data-silver-dialog-prev]').disabled=zoom===1;document.querySelector('[data-silver-dialog-next]').disabled=zoom===total;dialog.scrollTop=0};
 function open(n,button){zoom=n;opener=button;zoomRender();dialog.showModal();document.body.classList.add('silver-modal-open')}
 document.querySelectorAll('[data-silver-zoom]').forEach(b=>b.addEventListener('click',()=>open(Number(b.dataset.silverZoom),b)));document.querySelector('[data-silver-reader-zoom]').addEventListener('click',e=>open(index+1,e.currentTarget));document.querySelector('[data-silver-close]').addEventListener('click',()=>dialog.close());for(const [sel,dir] of [['[data-silver-dialog-prev]',-1],['[data-silver-dialog-next]',1]])document.querySelector(sel).addEventListener('click',()=>{zoom=Math.max(1,Math.min(total,zoom+dir));zoomRender()});dialog.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();zoom=Math.max(1,Math.min(total,zoom+(e.key==='ArrowRight'?1:-1)));zoomRender()}});dialog.addEventListener('close',()=>{document.body.classList.remove('silver-modal-open');opener?.focus()});dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});render();
});
